/* DRAMの容量（技術の年から）：1970年の1キロビットから3年で4倍、1997年からは伸びが鈍る */
function fdDramLabel(ty) {
  const b = ty <= 1997 ? 10 + 2 * (ty - 1970) / 3 : 28 + (ty - 1997) / 4.3;
  const bits = Math.pow(2, Math.max(8, Math.round(b)));
  return bits >= 2 ** 30 ? `${fmtNum(bits / 2 ** 30, 0)}ギガビット` : bits >= 2 ** 20 ? `${fmtNum(bits / 2 ** 20, 0)}メガビット` : `${fmtNum(bits / 2 ** 10, 0)}キロビット`;
}
